(function () {
  
    const tracks = document.querySelectorAll(".marquee-track");
    
    tracks.forEach((track) => {
     
        const direction = track.getAttribute("data-direction") === "right" ? "right" : "left";
        const baseSpeed = parseFloat(track.getAttribute("data-speed")) || 1.5;
  

        track.innerHTML += track.innerHTML;
  
        let position = 0;
        let speed = baseSpeed;
        let targetSpeed = baseSpeed;
  
        track.addEventListener("mouseenter", () => {
            targetSpeed = baseSpeed * 0.1; 
        });
  
        track.addEventListener("mouseleave", () => {
            targetSpeed = baseSpeed;
        });
  
        function animate() {
            speed += (targetSpeed - speed) * 0.05;
            
            if (direction === "left") {
                position -= speed;
            } else {
                position += speed;
            }
  
            const halfWidth = track.scrollWidth / 2;
  
            if (direction === "left" && Math.abs(position) >= halfWidth) {
                position += halfWidth;
            } else if (direction === "right" && position >= 0) {
                position -= halfWidth;
            }
  
            track.style.transform = `translateX(${position}px)`;
  
            requestAnimationFrame(animate);
        }
  
        if (direction === "right") {
           
            setTimeout(() => {
                position = -(track.scrollWidth / 2);
            }, 0);
        }
  
        animate();
    });
})();